vector<int> grundy(int n) {
    vector<int> g(n + 1), seen(n + 1, -1);
    for (int k = 1; k <= n; k++) {
        int d = (k - 1) / 2;
        for (int a = 1; a < k - a; a++) {
            int x = g[a] ^ g[k - a];
            if (x <= d) seen[x] = k;
        }
        while (g[k] <= d && seen[g[k]] == k) g[k]++;
    }
    return g;
}

